import { RegionSummarySchema } from '@jaga-daerah/contracts';
import type { RegionSummary } from '@jaga-daerah/contracts';

import regionsJson from '@/data/regions.json';

// Generated by `bun run etl:regions -- --export-web apps/web/src/data/regions.json` from the
// validated Kemendagri 2025 codes; parsed at build time so a malformed file fails the build.
export const REGIONS: readonly RegionSummary[] = RegionSummarySchema.array().parse(regionsJson);
